package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a claim edited into a correction unless it names, by number, a SETTLED claim of its person. */
public class CheckClaimCorrection {
    public void check(@Val Claim claim, @Val ClaimInput input, ClaimStore claims) throws InvalidSheetException {
        CheckCorrection.refuseUnsettled(claims, claim.getSheetId(), claim.getPersonId(), input);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated claim add or edit: the date already defaulted to the sheet's today; {@code corrects}
 *  the number of the claim a correction (a negative amount) corrects, null for any other claim;
 *  {@code ref} the external reference, spaces around it removed, null when none was given; {@code tags} its
 *  tags (see {@link Tags}), null when none were given. */
public record ClaimInput(BigDecimal amount, LocalDate date, String note, String user, String corrects, String ref,
        String tags) {

    public ClaimInput(BigDecimal amount, LocalDate date, String note, String user, String corrects, String ref) {
        this(amount, date, note, user, corrects, ref, null);
    }

    public ClaimInput(BigDecimal amount, LocalDate date, String note, String user, String corrects) {
        this(amount, date, note, user, corrects, null);
    }

    public ClaimInput(BigDecimal amount, LocalDate date, String note, String user) {
        this(amount, date, note, user, null);
    }

    /** Whether this is a correction: a negative amount. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim stands. Only OPEN, PENDING and SETTLED claims count toward the totals; a PENDING claim
 *  (settled by a clerk above the clerk limit, awaiting a steward) is handled as an OPEN one, except
 *  that a statement does not bind it while it is PENDING. A DELETED claim (a deleted DRAFT) counts nowhere,
 *  and may be restored to a DRAFT only on the sheet's today it was deleted (see {@link CheckClerkLimit}).
 *  A REVIEW claim (opened while its due is above the review threshold in force on its date) awaits a
 *  steward's review, which makes it OPEN; until then it counts in no total and has no number. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether a claim may move from this status to {@code next}: DRAFT to OPEN, OPEN to PENDING or
     *  SETTLED, PENDING to SETTLED (approved) or OPEN (rejected), and DRAFT, OPEN or PENDING to VOID;
     *  SETTLED to VOID too, though only a steward within days of settling it (see {@link CheckClerkLimit}).
     *  DRAFT to DELETED, and DELETED back to DRAFT (restored). DRAFT to REVIEW (opened above the review
     *  threshold), REVIEW to OPEN (reviewed) or VOID. VOID is final. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT || this == PENDING || this == REVIEW;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
            case REVIEW -> this == DRAFT;
        };
    }

    /** Whether a claim of this status may move to another person: DRAFT, OPEN or PENDING. */
    public boolean canMove() {
        return this == DRAFT || this == OPEN || this == PENDING;
    }

    /** Whether the claim is open: OPEN, or PENDING, which is handled as open. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** The audit event recorded when a claim moves to this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DELETED -> "CLAIM_DELETED";
            case DRAFT -> "CLAIM_DRAFTED";
            case REVIEW -> "CLAIM_REVIEW";
        };
    }

    /** The audit event recorded when a claim moves from {@code from} to this status: a PENDING claim
     *  settled is CLAIM_APPROVED, one moved back to OPEN is CLAIM_REJECTED, and a DELETED claim moved
     *  back to DRAFT is CLAIM_RESTORED. A REVIEW claim moved to OPEN is CLAIM_REVIEWED (then recorded
     *  as CLAIM_OPENED too, see {@link AuditClaimStatus}). */
    public String event(ClaimStatus from) {
        if (from == DELETED && this == DRAFT) {
            return "CLAIM_RESTORED";
        }
        if (from == PENDING && this == SETTLED) {
            return "CLAIM_APPROVED";
        }
        if (from == PENDING && this == OPEN) {
            return "CLAIM_REJECTED";
        }
        if (from == REVIEW && this == OPEN) {
            return "CLAIM_REVIEWED";
        }
        return event();
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;

/** The claim form's add, step by step, for a change that adds several claims at once (a paste). */
public final class ClaimAdding {
    private ClaimAdding() {
    }

    /** The claim form's rules on a claim typed for the person, before anything is stored: the claim as
     *  it would be stored. */
    public static ClaimInput check(String sheetId, Person person, ClaimRequest request, SettingStore settings,
            PeriodStore periods, ClaimStore claims, HolidayStore holidays) throws InvalidSheetException {
        ClaimInput input = ValidateClaim.check(sheetId, request, settings);
        ClaimPeriods.refuseClosed(periods, sheetId, ClaimPeriods.dueByOf(person, input.date(), settings, holidays));
        Retirement.refuseClaimDate(person, input.date());
        CheckCorrection.refuseUnsettled(claims, sheetId, person.getId(), input);
        CheckRef.refuseTaken(claims, sheetId, input, 0);
        return input;
    }

    /** Stores the checked claim as a DRAFT and records it as CLAIM_ADDED (and LATE_ENTRY for a late entry), then how it moved the figures. */
    public static Claim add(ClaimInput input, Person person, ClaimStore store, SettingStore settings,
            ClaimLogStore log, PeriodStore periods, RollupService rollups, Audit audit, HolidayStore holidays) {
        var before = rollups.snapshot(person.getSheetId());
        Claim claim = SaveClaimAdded.add(input, person, store, settings, log, periods, holidays);
        AuditClaimAdded.record(input, person, claim, before, audit, rollups);
        return claim;
    }
}
    public ClaimStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Claim> list(String sheetId) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY listed DESC", ROW, sheetId);
    }

    /** The sheet's claims as they stood at the end of the date (see {@link History}), newest first. */
    public List<Claim> listAsOf(String sheetId, LocalDate date) {
        return jdbc.query("SELECT * FROM " + History.asOf("claim", "id", date) + " WHERE sheet_id = ? ORDER BY listed DESC",
                ROW, sheetId);
    }

    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person's claim with the number, or null when they have none. */
    public Claim findByNumber(String sheetId, long personId, String number) {
        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ?", ROW,
                sheetId, personId, number);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Every tag ever carried by a claim or a person on the sheet (by their history, see {@link History}), as stored (see
     *  {@link Tags}); up to the end of {@code date} when given, else up to now. */
59:    public long getPersonId() { return personId; }
